import { readFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { migrate } from 'drizzle-orm/node-postgres/migrator';
import type pg from 'pg';
import type { Db } from './client.js';

/**
 * Forward migrations are generated by drizzle-kit into `drizzle/`.
 * Every forward migration `<tag>.sql` MUST have a hand-written
 * `drizzle/rollback/<tag>.sql` that undoes it (checked by the API tests).
 */
export const migrationsFolder = fileURLToPath(new URL('../../drizzle', import.meta.url));

const MIGRATIONS_TABLE = 'drizzle.__drizzle_migrations';

export async function runMigrations(db: Db): Promise<void> {
  await migrate(db, { migrationsFolder });
}

interface Journal {
  entries: { idx: number; when: number; tag: string }[];
}

export async function readJournal(folder = migrationsFolder): Promise<Journal> {
  const raw = await readFile(path.join(folder, 'meta', '_journal.json'), 'utf8');
  return JSON.parse(raw) as Journal;
}

/**
 * Undo the most recently applied migration: run its rollback SQL and remove
 * its bookkeeping row so `runMigrations` would apply it again.
 * Returns the rolled-back tag, or null when nothing is applied.
 */
export async function rollbackLastMigration(
  pool: pg.Pool,
  folder = migrationsFolder,
): Promise<string | null> {
  const journal = await readJournal(folder);
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    const exists = await client.query<{ present: boolean }>(
      `SELECT to_regclass($1) IS NOT NULL AS present`,
      [MIGRATIONS_TABLE],
    );
    if (!exists.rows[0]?.present) {
      await client.query('ROLLBACK');
      return null;
    }
    const last = await client.query<{ id: number; created_at: string }>(
      `SELECT id, created_at FROM ${MIGRATIONS_TABLE} ORDER BY created_at DESC LIMIT 1 FOR UPDATE`,
    );
    const row = last.rows[0];
    if (!row) {
      await client.query('ROLLBACK');
      return null;
    }
    const entry = journal.entries.find((e) => e.when === Number(row.created_at));
    if (!entry) {
      throw new Error(`Applied migration (created_at=${row.created_at}) is not in the journal`);
    }
    const sql = await readFile(path.join(folder, 'rollback', `${entry.tag}.sql`), 'utf8');
    await client.query(sql);
    await client.query(`DELETE FROM ${MIGRATIONS_TABLE} WHERE id = $1`, [row.id]);
    await client.query('COMMIT');
    return entry.tag;
  } catch (error) {
    await client.query('ROLLBACK').catch(() => undefined);
    throw error;
  } finally {
    client.release();
  }
}
